use vstd::prelude::*;

verus! {

spec fn rotated<T>(s: Seq<T>, n: nat) -> Seq<T> {
    s.subrange(n as int, s.len() as int) + s.subrange(0, n as int)
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list@.len() > 0,
        0 < n < list@.len(),
    ensures
        new_list@.len() == list@.len(),
        new_list@ == rotated(list@, n as nat),
{
    let len = list.len();
    assert!(len > 0, "list must be non-empty");
    assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[n..]);
    // After first extend: new_list == list[n..]
    assert(new_list@ == list@.subrange(n as int, len as int));

    new_list.extend_from_slice(&list[..n]);
    // After second extend: concatenation matches the spec rotation
    assert(new_list@ == list@.subrange(n as int, len as int) + list@.subrange(0, n as int));
    assert(new_list@ == rotated(list@, n as nat));

    new_list
}

} // verus!

